        private static int Scalar(string data, int p) { return data[p] * 65536 + data[p + 1]; }
        private static int Find(string data, int stride, int scalar)
        {
            int low = 0, high = data.Length / stride - 1;
            while (low <= high)
            {
                int mid = low + (high - low) / 2, p = mid * stride, key = Scalar(data, p);
                if (key < scalar) low = mid + 1;
                else if (key > scalar) high = mid - 1;
                else return p;
            }
            return -1;
        }
        internal static int CombiningClass(int scalar)
        {
            int p = Find(CombiningClasses, 3, scalar);
            return p < 0 ? 0 : CombiningClasses[p + 2];
