        internal static int[] Decompose(int scalar)
        {
            int p = Find(DecompositionKeys, 4, scalar);
            if (p < 0) return null;
            int offset = DecompositionKeys[p + 2], count = DecompositionKeys[p + 3];
            var result = new int[count];
            for (int i = 0; i < count; i++) result[i] = Scalar(DecompositionValues, offset + i * 2);
            return result;
