        internal static int Compose(int first, int second)
        {
            int low = 0, high = Compositions.Length / 6 - 1;
            while (low <= high)
            {
                int mid = low + (high - low) / 2, p = mid * 6, a = Scalar(Compositions, p), b = Scalar(Compositions, p + 2);
                if (a < first || (a == first && b < second)) low = mid + 1;
                else if (a > first || b > second) high = mid - 1;
                else return Scalar(Compositions, p + 4);
            }
            return -1;
        }
        private static bool InRanges(string ranges, int scalar)
        {
            int low = 0, high = ranges.Length / 4 - 1;
            while (low <= high)
            {
